function isSameTree(p: TreeNode | null, q: TreeNode | null): boolean {
  // Оба поддерева пустые — совпадают
  if (p === null && q === null) {
    return true;
  }

  // Пусто только одно — структура разная
  if (p === null || q === null) {
    return false;
  }

  // Оба узла есть: значения должны совпасть,
  // а левые и правые поддеревья — быть одинаковыми попарно
  return p.val === q.val && isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
}

// Время: O(n) — каждый узел сравнивается не более одного раза
// Память: O(h) — стек рекурсии
